source.@value:
rule "Flint2 portable TCP SYN"
when
    to_string($message.event_module) == "flint2" && (to_string($message.event_dataset) == "flint2.network_flow" && to_string($message.network_transport) == "tcp" && has_field("flint2_tcp_flags") && to_long($message.flint2_tcp_flags) == 2)
then
    set_field("flint2_dashboard_tcp_flags", "SYN");
    set_field("flint2_dashboard_tcp_syn_only", true);
    set_field("flint2_dashboard_flow_indicator", true);
    set_field("flint2_dashboard_flow_indicator_type", "TCP_SYN");
end

pipeline "Flint2 portable dashboard enrichment"
stage 0 match either
    rule "Flint2 portable megabytes";
    rule "Flint2 portable peer inbound";
    rule "Flint2 portable peer outbound";
    rule "Flint2 portable peer internal";
    rule "Flint2 portable high_byte_flow";
    rule "Flint2 portable high_packet_flow";
    rule "Flint2 portable TCP SYN";
    rule "Flint2 portable TCP SYN-ACK";
    rule "Flint2 portable TCP ACK";
    rule "Flint2 portable TCP RST";
    rule "Flint2 portable TCP FIN";
    rule "Flint2 portable UDP volume";
    rule "Flint2 portable service destination";
    rule "Flint2 portable service source";
    rule "Flint2 portable firewall service";
    rule "Flint2 portable private destination";
end
